import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"计量匹配","description":"","frontmatter":{"title":"计量匹配","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/metrology-matching.md","filePath":"litho/metrology-matching.md","lastUpdated":1789023840000}'),E={name:"litho/metrology-matching.md"};function c(m,a,A,_,f,B){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="计量匹配" tabindex="-1">计量匹配 <a class="header-anchor" href="#计量匹配" aria-label="Permalink to &quot;计量匹配&quot;">​</a></h1><div class="epigraph"><p>两台 CD-SEM、两套套刻机报的纳米差一截偏置时，APC 会把机台差当成工艺漂移去补。匹配是让法律量可比，不是把硬件调成同一序列号。</p><footer>—— 对照计量机匹配 / correlation；SEMI 对量测相关与工具匹配的通称</footer></div><p><a href="/litho/lot-disposition-rework">上一课</a>用计量做放行。缺口是：放行与 APC 若混用未匹配的机台，限会跳、控制器会振荡。<a href="/litho/tool-matching">机台匹配</a> 已谈扫描机指纹；本课钉<strong>计量侧</strong>匹配。边缘场与部分场为何特别难量、难补，留给[下一课](/litho/edge-field-partial）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CD-SEM 算法、电压、收缩、套刻的 IBO/DBO 与建模，都给出带偏置的数。黄金片或相关片在机台间循环，估偏置与斜率。不匹配：同一批在 A 机合格、B 机超规格，分派抽签；APC 在 A 学到的剂量传到 B 计量时反号。</p><p>缺口是<strong>参考层级</strong>，不是再讲边缘检测。要有参考机（或参考算法版本），其余报偏差。算法升级等于新机，要重新相关，控制图换版。</p><h3 id="匹配不是校准到真值" tabindex="-1">匹配不是校准到真值 <a class="header-anchor" href="#匹配不是校准到真值" aria-label="Permalink to &quot;匹配不是校准到真值&quot;">​</a></h3><p>没有真空里的真 CD。匹配是机台间相对，外加与电学或 TEM 的周期性锚。把 SEM 匹配到「设计 CD」是类别错误。OCD 与 SEM 相关尤其要声明材料栈，换硬掩模即失配。</p><p><span class="marginnote">套刻匹配含标记类型。IBO 与 DBO 的差不是匹配能消掉的物理， holistic 要选一种当回路主量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>循环：监控片定期跑多机，估 offset/gain，超限则锁机待修。与 APC：补偿值必须带「按参考机尺度」。与 SPC：控制限在参考尺度上建，单机用匹配后的数。TEM/截面做低频锚，样本少，只校正慢偏置。</p><p>匹配片的图形与材料栈要接近产品，否则 OCD/SEM 相关在产品上失真。算法或食谱升级当天重跑循环片，并冻结 APC 直到新 \\(a,b\\) 写入——这是计量侧的「事件重置」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>观测 \\(y_i = a_i y_\\mathrm{ref} + b_i + \\varepsilon\\)。匹配估 \\(a,b\\)。斜率 \\(a\\neq 1\\) 时，规格带宽在该机上被缩放，必须改限或禁该机进回路。噪声 \\(\\varepsilon\\) 进抽样不确定度，过匹配（把噪声当偏置每天改）会把随机写进 APC。</p>',14)),(e(),s(p,null,{default:o(()=>[d(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%8F%82%E8%80%83%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20GOLD%5B%22%E5%BE%AA%E7%8E%AF%E7%89%87%20%2F%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20TOOL%5B%22%E5%85%B6%E4%BB%96%E8%AE%A1%E9%87%8F%E6%9C%BA%22%5D%20--%3E%20GOLD%0A%20%20GOLD%20--%3E%20AB%5B%22offset%20%2F%20gain%22%5D%0A%20%20AB%20--%3E%20APC%5B%22%E5%90%8C%E4%B8%80%E5%B0%BA%E5%BA%A6%E7%9A%84%20APC%20%2F%20%E5%88%86%E6%B4%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>offset/gain 把各机拉到参考尺度。斜率不为一时，规格带宽被缩放，不能只加一个偏置就进回路。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不匹配扫描机光学（那是 tool matching）。不把未公开的相关残差当规格。本课不写虚拟计量模型训练。</p><p>后课默认：所有回路与分派用匹配后的尺度。下一课边缘与部分场往往是匹配最差、抽样最少的区域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计量匹配让 APC 与分派共用尺度，算法升级即新机。</li><li>无绝对真 CD；TEM 只做低频锚。</li><li>斜率不为 1 时不能只加偏置。</li><li>算法升级当天重跑循环片并冻结 APC。</li><li>出处：计量相关与 tool matching 通称；SEMI 量测相关。</li></ul>',6))])}const u=r(E,[["render",c]]);export{g as __pageData,u as default};
